{"task": {"current_case": {"facts": "In 2017, Alice was paid $33200. Alice and Bob have been married since Feb 3rd, 2017. Alice has been blind since March 20, 2016.", "question": "Section 63(f)(2)(A) applies to Alice in 2017."}, "unchanged_legal_program": {"input_fields_json": "{"query_person":{"type":"string","description":"被查询纳税人本人；配偶记录不满足该目标谓词。"},"query_year":{"type":"integer","description":"被查询的公历纳税年度；终结日为该年 12 月 31 日。"},"blindness_status_records":{"type":"array|null","description":"明确时点状态；每个对象严格为 {person:string,as_of_date:string,is_blind:boolean}，日期为 YYYY-MM-DD。只有终结日状态直接决定目标。null 表示未读取或未解析。"},"blindness_intervals":{"type":"array|null","description":"明确失明区间；每个对象严格为 {person:string,start_date:string,end_date:string|null,open_ended:boolean}，区间包含端点。end_date 为 null 仅在 open_ended 为 true 时明确持续，否则结束未知。null 表示未解析。"},"blindness_onsets":{"type":"array|null","description":"明确发病及持续事实；每个对象严格为 {person:string,onset_date:string,persists_through_date:string|null,continues_indefinitely:boolean}。持续截止日包含在内；无截止日仅在 continues_indefinitely 为 true 时支持持续。null 表示未解析。"}}", "name": "taxpayer_blind_year_end", "program": "def apply(inputs,premises):
    person=inputs.get('query_person')
    year=inputs.get('query_year')
    if not isinstance(person,str) or type(year) is not int:
        return {'handled':False,'answer':None}
    close=str(year)+'-12-31'
    calendar_year(close)
    statuses=inputs.get('blindness_status_records')
    intervals=inputs.get('blindness_intervals')
    onsets=inputs.get('blindness_onsets')
    positive=False; negative=False; uncertain=False
    if statuses is None:
        uncertain=True
    else:
        if not isinstance(statuses,list):
            raise TypeError('blindness_status_records must be an array or null')
        for record in statuses:
            if not isinstance(record,dict):
                raise TypeError('Each blindness status must be an object')
            subject=record.get('person'); date=record.get('as_of_date'); blind=record.get('is_blind')
            if not isinstance(subject,str) or not isinstance(date,str) or type(blind) is not bool:
                raise ValueError('Malformed blindness status')
            calendar_year(date)
            if subject==person and date==close:
                if blind:
                    positive=True
                else:
                    negative=True
    if intervals is None:
        uncertain=True
    else:
        if not isinstance(intervals,list):
            raise TypeError('blindness_intervals must be an array or null')
        for record in intervals:
            if not isinstance(record,dict):
                raise TypeError('Each blindness interval must be an object')
            subject=record.get('person'); start=record.get('start_date'); end=record.get('end_date'); opened=record.get('open_ended')
            if not isinstance(subject,str) or not isinstance(start,str) or type(opened) is not bool:
                raise ValueError('Malformed blindness interval')
            calendar_year(start)
            if end is not None:
                if not isinstance(end,str) or opened:
                    raise ValueError('A closed blindness interval requires open_ended false')
                calendar_year(end)
                if end<start:
                    raise ValueError('Blindness interval ends before it begins')
            if subject!=person or start>close:
                continue
            if end is not None and end>=close:
                positive=True
            elif end is None and opened:
                positive=True
            elif end is None:
                uncertain=True
    if onsets is None:
        uncertain=True
    else:
        if not isinstance(onsets,list):
            raise TypeError('blindness_onsets must be an array or null')
        for record in onsets:
            if not isinstance(record,dict):
                raise TypeError('Each blindness onset must be an object')
            subject=record.get('person'); start=record.get('onset_date'); end=record.get('persists_through_date'); ongoing=record.get('continues_indefinitely')
            if not isinstance(subject,str) or not isinstance(start,str) or type(ongoing) is not bool:
                raise ValueError('Malformed blindness onset')
            calendar_year(start)
            if end is not None:
                if not isinstance(end,str) or ongoing:
                    raise ValueError('A bounded onset record requires continues_indefinitely false')
                calendar_year(end)
                if end<start:
                    raise ValueError('Blindness persistence ends before onset')
            if subject!=person or start>close:
                continue
            if end is not None and end>=close:
                positive=True
            elif end is None and ongoing:
                positive=True
            elif end is None:
                uncertain=True
    if positive and negative:
        return {'handled':False,'answer':None}
    if positive:
        return {'handled':True,'answer':'Entailment'}
    if negative:
        return {'handled':True,'answer':'Contradiction'}
    if uncertain:
        return {'handled':False,'answer':None}
    return {'handled':True,'answer':'Contradiction'}", "query_clause": "63(f)(2)(A)", "scope": "exact_clause", "source_quote": "(A) for himself if he is blind at the close of the taxable year,"}}, "output_schema": {"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["views"], "properties": {"views": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["query_person", "query_year", "dated_statuses", "blindness_facts", "witnesses"], "properties": {"query_person": {"type": ["string", "null"]}, "query_year": {"type": ["integer", "null"]}, "dated_statuses": {"type": ["array", "null"], "items": {"type": "object", "additionalProperties": false, "required": ["person", "as_of_date", "is_blind"], "properties": {"person": {"type": "string"}, "as_of_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}, "is_blind": {"type": "boolean"}}}}, "blindness_facts": {"type": ["array", "null"], "items": {"oneOf": [{"type": "object", "additionalProperties": false, "required": ["person", "form", "start_date"], "properties": {"person": {"type": "string"}, "form": {"const": "ongoing_since"}, "start_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}, {"type": "object", "additionalProperties": false, "required": ["person", "form", "start_date"], "properties": {"person": {"type": "string"}, "form": {"const": "onset_only"}, "start_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}, {"type": "object", "additionalProperties": false, "required": ["person", "form", "start_date", "end_date"], "properties": {"person": {"type": "string"}, "form": {"const": "closed_interval"}, "start_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}, "end_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}, {"type": "object", "additionalProperties": false, "required": ["person", "form", "start_date", "through_date"], "properties": {"person": {"type": "string"}, "form": {"const": "ongoing_through"}, "start_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}, "through_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}]}}, "witnesses": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["field", "quote"], "properties": {"field": {"enum": ["facts", "question"]}, "quote": {"type": "string", "minLength": 1}}}}}}}}}}
